// systemUsage displays the usage of the system command and its subcommands.
func systemUsage() {
	fmt.Fprintln(os.Stderr, `Service is the system service interface.`)
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] system COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, `    health: Health implements health.`)
	fmt.Fprintln(os.Stderr, `    echo: Echo implements echo.`)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s system COMMAND --help\n", os.Args[0])
}
func systemHealthUsage() {
	// Header with flags
	fmt.Fprintf(os.Stderr, "%s [flags] system health", os.Args[0])
	fmt.Fprintln(os.Stderr)

	// Description
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, `Health implements health.`)

	// Flags list

	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Example:")
	fmt.Fprintf(os.Stderr, "    %s %s\n", os.Args[0], "system health")
}

func systemEchoUsage() {
	// Header with flags
	fmt.Fprintf(os.Stderr, "%s [flags] system echo", os.Args[0])
	fmt.Fprint(os.Stderr, " -name STRING")
	fmt.Fprintln(os.Stderr)

	// Description
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, `Echo implements echo.`)

	// Flags list
	fmt.Fprintln(os.Stderr, `    -name STRING: `)

	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Example:")
	fmt.Fprintf(os.Stderr, "    %s %s\n", os.Args[0], "system echo --name \"h8\"")
}

